package com.gielinorcartography;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.UUID;
import net.runelite.client.RuneLite;

/**
 * A random per-installation secret, persisted under the .runelite directory, sent alongside
 * every claim/steal request. The backend binds it to a player name on that name's first-ever
 * claim, then rejects any later claim under that name from a different token - stopping someone
 * from spoofing another player's claims over plain HTTP without their token file. Not real
 * auth (anyone with filesystem access to that token file could still impersonate that
 * installation), just enough to stop casual cheating among LAN players who don't have access to
 * each other's machines.
 */
final class PlayerToken
{
	private static final String DIRECTORY_NAME = "gielinor-cartography";
	private static final String FILE_NAME = "player-token.txt";

	private PlayerToken()
	{
	}

	static String loadOrCreate() throws IOException
	{
		Path dir = RuneLite.RUNELITE_DIR.toPath().resolve(DIRECTORY_NAME);
		Files.createDirectories(dir);

		Path file = dir.resolve(FILE_NAME);
		if (Files.exists(file))
		{
			String existing = new String(Files.readAllBytes(file), StandardCharsets.UTF_8).trim();
			if (!existing.isEmpty())
			{
				return existing;
			}
		}

		String token = UUID.randomUUID().toString();
		Files.write(file, token.getBytes(StandardCharsets.UTF_8));
		return token;
	}
}

package com.gielinorcartography;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Talks to the Gielinor Cartography backend over HTTP. All calls are async (OkHttp's enqueue()) -
 * callbacks run on OkHttp's thread pool, never the client thread, so callers must hop back via
 * ClientThread before touching anything from the game client.
 */
@Slf4j
@Singleton
class GielinorCartographyClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int HTTP_LOCKED = 423;
	// The one and only backend this plugin ever talks to - not user-configurable, since there's
	// nothing meaningful to point it at besides the real Gielinor Cartography server.
	private static final String SERVER_URL = "https://gc.gielinorcartography.uk";

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	GielinorCartographyClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	void getTaskState(String taskId, Consumer<TaskState> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = HttpUrl.parse(SERVER_URL + "/task")
			.newBuilder()
			.addQueryParameter("id", taskId)
			.build();
		Request request = new Request.Builder()
			.url(url)
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						onError.accept("HTTP " + r.code());
						return;
					}

					onSuccess.accept(gson.fromJson(r.body().charStream(), TaskState.class));
				}
				catch (Exception e)
				{
					log.warn("Failed to parse task state", e);
					onError.accept(e.getMessage());
				}
			}
		});
	}

	void getAllTaskStates(Consumer<List<TaskState>> onSuccess, Consumer<String> onError)
	{
		Request request = new Request.Builder()
			.url(SERVER_URL + "/tasks")
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						onError.accept("HTTP " + r.code());
						return;
					}

					Type listType = new TypeToken<List<TaskState>>()
					{
					}.getType();
					onSuccess.accept(gson.fromJson(r.body().charStream(), listType));
				}
				catch (Exception e)
				{
					log.warn("Failed to parse task states", e);
					onError.accept(e.getMessage());
				}
			}
		});
	}

	void getLeaderboard(Consumer<List<PlayerRanking>> onSuccess, Consumer<String> onError)
	{
		Request request = new Request.Builder()
			.url(SERVER_URL + "/leaderboard")
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						onError.accept("HTTP " + r.code());
						return;
					}

					Type listType = new TypeToken<List<PlayerRanking>>()
					{
					}.getType();
					onSuccess.accept(gson.fromJson(r.body().charStream(), listType));
				}
				catch (Exception e)
				{
					log.warn("Failed to parse leaderboard", e);
					onError.accept(e.getMessage());
				}
			}
		});
	}

	void completeTask(String taskId, String player, Integer totalLevel, String playerToken, Consumer<CompletionResult> onSuccess, BiConsumer<String, Long> onLocked, Consumer<String> onError)
	{
		String json = gson.toJson(new CompleteRequest(taskId, player, totalLevel, playerToken));
		RequestBody body = RequestBody.create(JSON, json);
		Request request = new Request.Builder()
			.url(SERVER_URL + "/complete")
			.post(body)
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.code() == HTTP_LOCKED)
					{
						LockedInfo info = gson.fromJson(r.body().charStream(), LockedInfo.class);
						onLocked.accept(info.owner, info.unlocksAt);
						return;
					}

					if (!r.isSuccessful())
					{
						onError.accept("HTTP " + r.code());
						return;
					}

					onSuccess.accept(gson.fromJson(r.body().charStream(), CompletionResult.class));
				}
				catch (Exception e)
				{
					log.warn("Failed to parse completion result", e);
					onError.accept(e.getMessage());
				}
			}
		});
	}

	// playerToken is a per-installation secret (see PlayerToken) the backend binds to a player
	// name on that name's first claim - basic protection against spoofing someone else's claims
	// over plain HTTP, not real account auth.
	private static class CompleteRequest
	{
		final String taskId;
		final String player;
		final Integer totalLevel;
		final String playerToken;

		CompleteRequest(String taskId, String player, Integer totalLevel, String playerToken)
		{
			this.taskId = taskId;
			this.player = player;
			this.totalLevel = totalLevel;
			this.playerToken = playerToken;
		}
	}
}

package com.gielinorcartography;

/**
 * Mirrors the JSON body returned by a successful POST /complete on the backend.
 */
class CompletionResult
{
	String id;
	String owner;
	Long lastTaken;
	int cooldownSeconds;
	int pointsAwarded;
	int stealBonus;
	boolean stolen;
	String previousOwner;
}

package com.gielinorcartography;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * Ranks every player by total points, filterable to one exclusive total-level tier or "Global"
 * (everyone). Defaults to the viewer's own tier the first time real data arrives, then leaves
 * the selection alone so browsing a different tier doesn't keep getting reset. update() is only
 * ever called from the Swing EDT - the plugin is responsible for that guarantee, not this class.
 * A tab's content inside GielinorCartographyPanel, not a top-level sidebar panel itself.
 */
class GielinorCartographyLeaderboardPanel extends JPanel
{
	private static final String GLOBAL = "Global";

	private final JComboBox<String> tierFilter;
	private final JPanel rowContainer = new JPanel();

	private List<PlayerRanking> lastRankings = Collections.emptyList();
	private String lastLocalPlayerName;
	private boolean hasSetDefaultTier;

	GielinorCartographyLeaderboardPanel()
	{
		tierFilter = new JComboBox<>(tierOptions());
		tierFilter.addActionListener(e -> render());

		rowContainer.setLayout(new BoxLayout(rowContainer, BoxLayout.Y_AXIS));

		setLayout(new BorderLayout(0, 6));
		add(tierFilter, BorderLayout.NORTH);
		add(rowContainer, BorderLayout.CENTER);
	}

	private static String[] tierOptions()
	{
		LeaderboardTier[] tiers = LeaderboardTier.values();
		String[] options = new String[tiers.length + 1];
		options[0] = GLOBAL;
		for (int i = 0; i < tiers.length; i++)
		{
			options[i + 1] = tiers[i].label;
		}
		return options;
	}

	void update(List<PlayerRanking> rankings, String localPlayerName, Integer localTotalLevel)
	{
		lastRankings = rankings;
		lastLocalPlayerName = localPlayerName;

		if (!hasSetDefaultTier && localTotalLevel != null)
		{
			tierFilter.setSelectedItem(LeaderboardTier.of(localTotalLevel).label);
			hasSetDefaultTier = true;
		}

		render();
	}

	private void render()
	{
		rowContainer.removeAll();

		String selectedTier = (String) tierFilter.getSelectedItem();

		// Already sorted by total points descending by the backend - filtering preserves order.
		List<PlayerRanking> filtered = new ArrayList<>();
		for (PlayerRanking ranking : lastRankings)
		{
			if (GLOBAL.equals(selectedTier)
				|| (ranking.totalLevel != null && LeaderboardTier.of(ranking.totalLevel).label.equals(selectedTier)))
			{
				filtered.add(ranking);
			}
		}

		int rank = 1;
		for (PlayerRanking ranking : filtered)
		{
			boolean isYou = lastLocalPlayerName != null && lastLocalPlayerName.equals(ranking.name);
			rowContainer.add(buildRow(rank, ranking, isYou));
			rowContainer.add(Box.createVerticalStrut(2));
			rank++;
		}
		// Without this, BoxLayout would stretch the last (or only) row to fill any leftover
		// vertical space instead of leaving it empty below the rows, which is what made a single
		// entry look like it was floating in the middle of the panel.
		rowContainer.add(Box.createVerticalGlue());

		rowContainer.revalidate();
		rowContainer.repaint();
	}

	private static JPanel buildRow(int rank, PlayerRanking ranking, boolean isYou)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(0f);

		Color textColor = isYou ? ColorScheme.BRAND_ORANGE : Color.WHITE;

		JLabel rankLabel = new JLabel("#" + rank);
		rankLabel.setForeground(textColor);

		JLabel nameLabel = new JLabel(ranking.name + " — " + ranking.totalPoints + " pts");
		nameLabel.setForeground(textColor);

		row.add(rankLabel, BorderLayout.WEST);
		row.add(nameLabel, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}
}

package com.gielinorcartography;

import java.awt.Color;

/**
 * The single source of truth for a task's status color, shared by the sidebar panel and the
 * world map markers so they can never disagree on what a color means.
 */
enum TaskStatus
{
	UNCLAIMED,
	AVAILABLE,
	LOCKED,
	OWNED_BY_YOU;

	static TaskStatus compute(TaskState state, String localPlayerName, long nowEpochSeconds)
	{
		if (state.owner == null)
		{
			return UNCLAIMED;
		}

		if (state.owner.equals(localPlayerName))
		{
			return OWNED_BY_YOU;
		}

		long unlocksAt = state.lastTaken + state.cooldownSeconds;
		return nowEpochSeconds >= unlocksAt ? AVAILABLE : LOCKED;
	}

	Color color()
	{
		switch (this)
		{
			case UNCLAIMED:
				return Color.GRAY;
			case AVAILABLE:
				return Color.RED;
			case LOCKED:
				return Color.BLACK;
			case OWNED_BY_YOU:
				return Color.GREEN;
			default:
				throw new IllegalStateException("Unhandled status: " + this);
		}
	}
}

package com.gielinorcartography;

/**
 * A task's category is entirely derived from its completion type - no separate schema field,
 * since production and gathering tasks (both CHAT_MESSAGE_COUNT) are deliberately lumped
 * together as "Skilling" rather than needing a way to tell them apart.
 */
enum TaskCategory
{
	COMBAT("Combat"),
	SKILLING("Skilling"),
	STAND_IN_ZONE("Stand in Zone"),
	AGILITY("Agility");

	final String label;

	TaskCategory(String label)
	{
		this.label = label;
	}

	static TaskCategory of(TaskDefinition.CompletionType completionType)
	{
		switch (completionType)
		{
			case NPC_LOOT_COUNT:
				return COMBAT;
			case CHAT_MESSAGE_COUNT:
				return SKILLING;
			case HOLD:
				return STAND_IN_ZONE;
			case LOCATION_STAT_COUNT:
				return AGILITY;
			default:
				throw new IllegalStateException("Unhandled completion type: " + completionType);
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

